    "Active 256-bit TLS authenticated session will be cleanly terminated and local tokens cleared.": "सक्रिय २५६-बिट TLS प्रमाणीकृत सत्र सुरक्षितपणे समाप्त केले जाईल आणि स्थानिक टोकन साफ केले जातील.",
    "All cadastral transformations and PFMS disbursements are statutory records under RFCTLARR Act 2013 and reconciled with the Central PFMS Treasury Gateway.": "सर्व भू-नोंดणी फेरबदल आणि PFMS वाटप हे RFCTLARR कायदा २०१३ अंतर्गत वैधानिक नोंदी आहेत आणि केंद्रीय PFMS तिजोरी गेटवेशी जुळवले गेले आहेत.",
