    "All residential/commercial structures vacated and R&R alternative site possession delivered.": "सर्व निवासी/व्यावसायिक बांधकामे रिकामी केली आणि R&R पर्यायी जागेचा ताबा दिला.",
    "Requisition submitted under Section 3(e) of the RFCTLARR Act 2013 for construction of elevated viaduct, station pier foundations, and multimodal interchange at Hinjewadi IT Park Phase 1. Complete land schedule and socio-economic census records annexed.": "हिंजवडी आयटी पार्क टप्पा १ येथे उन्नत मार्ग, स्टेशन खांब पाया आणि मल्टीमॉडल इंटरचेंज बांधकामासाठी RFCTLARR कायदा २०१३ च्या कलम ३(e) अंतर्गत मागणी अर्ज सादर. संपूर्ण जमीन तपशील आणि सामाजिक-आर्थिक जनगणना नोंदी जोडल्या आहेत.",
    "Social Impact Assessment conducted by Gokhale Institute of Politics and Economics. Public hearings concluded at Hinjewadi Gram Panchayat with 86% stakeholder consent. Minimal displacement: only 3 agricultural out-houses affected.": "गोखले इन्स्टिट्यूट ऑफ पॉलिटिक्स अँड इकॉनॉमिक्सद्वारे सामाजिक प्रभाव मूल्यांकन (SIA) पूर्ण. हिंजवडी ग्रामपंचायतीत ८६% सहमतीने जनसुनावणी संपन्न. अल्प विस्थापन: केवळ ३ शेतघरे बाधित.",
    "Standing timber, fruit trees, and perennial crops valuated and signed by Horticulture Dept.": "झाडे, फळझाडे आणि बारमाही पिकांचे मूल्यांकन फलोत्पादन विभागाकडून प्रमाणित व स्वाक्षरीत.",
    "Survey stones planted and boundary coordinates verified on site by Head Surveyor.": "हद्द निश्चितीचे दगड बसवले आणि मुख्य भूमापकाद्वारे जागेवर सीमा निर्देशांकांची पडताळणी पूर्ण केली.",
    "Pucca constructed dwelling (Min 50 m²) or ₹1.5 Lakh housing grant in model colony.": "पक्के घर (किमान ५० चौ.मी.) किंवा पुनर्वसन वसाहतीमध्ये ₹१.५ लाख गृहनिर्माण अनुदान.",
    "₹3,000 per month for 12 months or job skill training quota enrolled.": "₹३,००० दरमहा १२ महिन्यांसाठी किंवा कौशल्य प्रशिक्षण कोट्यामध्ये प्रवेश.",
    "₹50,000 per displaced rural family disbursed via Direct Benefit Transfer.": "प्रत्येक विस्थापित ग्रामीण कुटुंबाला थेट लाभ हस्तांतरण (DBT) द्वारे ₹५०,००० वाटप.",
