    "Central Ministry Dashboard: Review nationwide multi-state corridors, oversee statutory compliance audits, and MIS velocity curves.": "কেন্দ্রীয় মন্ত্রক ড্যাশবোর্ড: দেশব্যাপী বহু-রাজ্য করিডোর পর্যালোচনা, সংবিধিবদ্ধ সম্মতি অডিট এবং MIS গতির তদারকি করুন।",
    "State Revenue Directorate Dashboard: Monitor district land revenue operations, gazette releases, and inter-agency coordination.": "রাজ্য রাজস্ব পরিদপ্তর ড্যাশবোর্ড: জেলা ভূমি রাজস্ব কার্যক্রম, গেজেট প্রকাশ এবং আন্তঃসংস্থা সমন্বয় পর্যবেক্ষণ করুন।",
    "District / CALA Officer Dashboard: Scrutinize land titles, conduct Section 15 inquiry hearings, and declare Section 23 awards.": "জেলা / CALA আধিকারিক ড্যাশবোর্ড: জমির স্বত্ব যাচাই করুন, ধারা ১৫ তদন্ত শুনানি পরিচালনা করুন এবং ধারা ২৩ অ্যাওয়ার্ড প্রদান করুন।",
