    "All cadastral transformations and PFMS disbursements are statutory records under RFCTLARR Act 2013 and reconciled with the Central PFMS Treasury Gateway.": "সমস্ত ক্যাডাস্ট্রাল রূপান্তর এবং PFMS বিতরণ RFCTLARR আইন ২০১৩ এর অধীনে সংবিধিবদ্ধ রেকর্ড এবং কেন্দ্রীয় PFMS ট্রেজারি গেটওয়ের সাথে সমন্বিত।",
