    "Requisition submitted under Section 3(e) of the RFCTLARR Act 2013 for construction of elevated viaduct, station pier foundations, and multimodal interchange at Hinjewadi IT Park Phase 1. Complete land schedule and socio-economic census records annexed.": "হিঞ্জেওয়াড়ি আইটি পার্ক ফেজ ১-এ এলিভেটেড ভায়াডাক্ট, স্টেশন পিয়ার ফাউন্ডেশন এবং মাল্টিমোডাল ইন্টারচেঞ্জ নির্মাণের জন্য RFCTLARR আইন ২০১৩ এর ধারা ৩(e) এর অধীনে রিকুইজিশন জমা দেওয়া হয়েছে। সম্পূর্ণ জমির তফসিল এবং আর্থ-সামাজিক আদমশুমারি রেকর্ড সংযুক্ত।",
    "Social Impact Assessment conducted by Gokhale Institute of Politics and Economics. Public hearings concluded at Hinjewadi Gram Panchayat with 86% stakeholder consent. Minimal displacement: only 3 agricultural out-houses affected.": "গোখলে ইনস্টিটিউট অফ পলিটিক্স অ্যান্ড ইকোনমিক্স দ্বারা সামাজিক প্রভাব মূল্যায়ন সম্পন্ন। হিঞ্জেওয়াড়ি গ্রাম পঞ্চায়েতে ৮৬% সম্মতিতে গণশুনানি সম্পন্ন। ন্যূনতম বাস্তুচ্যুতি: মাত্র ৩টি কৃষি ঘর ক্ষতিগ্রস্ত।",
