    "Verified against Statutory Cadastral Roll": "કાનૂની કેડસ્ટ્રલ રજિસ્ટર સામે ચકાસાયેલ",
    "Verify Audit Hash": "ઓડિટ હેશ ચકાસો",
    "Active 256-bit TLS authenticated session will be cleanly terminated and local tokens cleared.": "સક્રિય ૨૫૬-બીટ TLS પ્રમાણિત સત્ર સુરક્ષિત રીતે સમાપ્ત થશે અને સ્થાનિક ટોકન સાફ કરવામાં આવશે.",
    "All cadastral transformations and PFMS disbursements are statutory records under RFCTLARR Act 2013 and reconciled with the Central PFMS Treasury Gateway.": "તમામ કેડસ્ટ્રલ ફેરફારો અને PFMS વિતરણો RFCTLARR કાયદો ૨૦૧૩ હેઠળ કાનૂની રેકોર્ડ છે અને કેન્દ્રીય PFMS ટ્રેઝરી ગેટવે સાથે સુમેળ કરેલ છે.",
    "All required land parcels possessed under Section 16, 100% PFMS DBT compensation disbursed, and all displaced families resettled in model colony.": "કલમ ૧૬ હેઠળ તમામ જરૂરી જમીન પ્લોટનો કબજો મેળવ્યો, ૧૦૦% PFMS DBT વળતર વિતરિત, અને તમામ વિસ્થાપિત પરિવારોને આદર્શ વસાહતમાં પુનર્વસન કરાયું.",
    "All residential/commercial structures vacated and R&R alternative site possession delivered.": "તમામ રહેણાંક/વાણિજ્યિક માળખા ખાલી કરાવ્યા અને R&R વૈકલ્પિક પ્લોટનો કબજો સોંપ્યો.",
    "Requisition submitted under Section 3(e) of the RFCTLARR Act 2013 for construction of elevated viaduct, station pier foundations, and multimodal interchange at Hinjewadi IT Park Phase 1. Complete land schedule and socio-economic census records annexed.": "હિંજવડી આઈટી પાર્ક ફેઝ ૧ ખાતે એલિવેટેડ વાયડક્ટ, સ્ટેશન પિલર પાયા અને મલ્ટિમોડલ ઇન્ટરચેન્જ નિર્માણ માટે RFCTLARR કાયદો ૨૦૧૩ ની કલમ ૩(e) હેઠળ માંગણી સબમિટ કરી. સંપૂર્ણ જમીન શેડ્યૂલ અને સામાજિક-આર્થિક વસ્તી ગણતરી રેકોર્ડ જોડાયેલ છે.",
    "Social Impact Assessment conducted by Gokhale Institute of Politics and Economics. Public hearings concluded at Hinjewadi Gram Panchayat with 86% stakeholder consent. Minimal displacement: only 3 agricultural out-houses affected.": "ગોખલે ઇન્સ્ટિટ્યૂટ દ્વારા સામાજિક અસર આકારણી (SIA) પૂર્ણ. હિંજવડી ગ્રામ પંચાયતમાં ૮૬% સંમતિ સાથે લોક સુનાવણી પૂર્ણ. ન્યૂનતમ વિસ્થાપન: માત્ર ૩ કૃષિ મકાનો પ્રભાવિત.",
    "Standing timber, fruit trees, and perennial crops valuated and signed by Horticulture Dept.": "લાકડાના ઝાડ, ફળ આપતા વૃક્ષો અને બારમાસી પાકનું મૂલ્યાંકન બાગાયત વિભાગ દ્વારા પ્રમાણિત.",
    "Survey stones planted and boundary coordinates verified on site by Head Surveyor.": "સર્વેક્ષણ પથ્થરો લગાવ્યા અને મુખ્ય સર્વેયર દ્વારા સ્થળ પર સીમા કોઓર્ડિનેટ્સ ચકાસ્યા.",
    "Pucca constructed dwelling (Min 50 m²) or ₹1.5 Lakh housing grant in model colony.": "પાકું મકાન (ન્યૂનતમ ૫૦ ચો.મી.) અથવા મોડેલ સોસાયટીમાં ₹૧.૫ લાખનું આવાસ અનુદાન.",
    "₹3,000 per month for 12 months or job skill training quota enrolled.": "૧૨ મહિના માટે દર મહિને ₹૩,૦૦૦ અથવા કૌશલ્ય તાલીમ ક્વોટામાં પ્રવેશ.",
    "₹50,000 per displaced rural family disbursed via Direct Benefit Transfer.": "દરેક વિસ્થાપિત ગ્રામીણ પરિવારને ડાયરેક્ટ બેનિફિટ ટ્રાન્સફર (DBT) દ્વારા ₹૫૦,૦૦૦ વિતરિત.",
    "These remarks will be permanently committed to the immutable statutory audit log.": "આ ટિપ્પણીઓ કાયમી રૂપે વૈધાનિક ઓડિટ લોગમાં સાચવવામાં આવશે.",
    "Submit digital Form 1 proposals, upload corridor shapefiles, and track statutory clearance workflows.": "ડિજિટલ ફોર્મ ૧ દરખાસ્તો સબમિટ કરો, કોરિડોર શેપફાઇલ અપલોડ કરો અને કાનૂની મંજૂરી પ્રક્રિયા ટ્રેક કરો.",
