    "Central Ministry Dashboard: Review nationwide multi-state corridors, oversee statutory compliance audits, and MIS velocity curves.": "மத்திய அமைச்சக கட்டுப்பாட்டுப் பலகை: நாடு தழுவிய பல மாநில வழித்தடங்களை மதிப்பாய்வு செய்து சட்டப்பூர்வ இணக்க தணிக்கைகளைக் கண்காணிக்கவும்.",
    "State Revenue Directorate Dashboard: Monitor district land revenue operations, gazette releases, and inter-agency coordination.": "மாநில வருவாய் இயக்கக டாஷ்போர்டு: மாவட்ட நில வருவாய் செயல்பாடுகள், அரசிதழ் வெளியீடுகள் மற்றும் ஒருங்கிணைப்பைக் கண்காணிக்கவும்.",
    "District / CALA Officer Dashboard: Scrutinize land titles, conduct Section 15 inquiry hearings, and declare Section 23 awards.": "மாவட்ட / CALA அலுவலர் டாஷ்போர்டு: நில ஆவணங்களை ஆய்வு செய்து, பிரிவு 15 விசாரணை நடத்தி, பிரிவு 23 இழப்பீட்டு ஆணைகளை வெளியிடவும்.",
    "Project Implementing Agency: Submit alignment proposals, upload GIS shapefiles, and request Joint Measurement Surveys (JMS).": "திட்ட அமலாக்க முகமை: சீரமைப்பு முன்மொழிவுகளைச் சமர்ப்பித்து, GIS கோப்புகளைப் பதிவேற்றி, கூட்டு அளவீட்டு ஆய்வைக் (JMS) கோரவும்.",
    "Citizen Transparency Portal: Search survey records, check compensation solatium calculations, and file hearing objections.": "குடிமக்கள் வெளிப்படைத்தன்மை போர்டல்: நில அளவை ஆவணங்களைத் தேடவும், இழப்பீட்டுக் கணக்கீட்டைச் சரிபார்க்கவும், ஆட்சேபனைகளைப் பதிவு செய்யவும்.",
