    "Verified against Statutory Cadastral Roll": "చట్టబద్ధమైన కాడస్ట్రల్ రికార్డుల ప్రకారం ధృవీకరించబడింది",
    "Verify Audit Hash": "ఆడిట్ హ్యాష్‌ను ధృవీకరించండి",
    "Active 256-bit TLS authenticated session will be cleanly terminated and local tokens cleared.": "క్రియాశీల 256-బిట్ TLS ప్రామాణీకరించబడిన సెషన్ సురక్షితంగా ముగించబడుతుంది మరియు స్థానిక టోకెన్‌లు క్లియర్ చేయబడతాయి.",
    "All cadastral transformations and PFMS disbursements are statutory records under RFCTLARR Act 2013 and reconciled with the Central PFMS Treasury Gateway.": "అన్ని కాడస్ట్రల్ మార్పులు మరియు PFMS పంపిణీలు RFCTLARR చట్టం 2013 ప్రకారం చట్టబద్ధమైన రికార్డులు మరియు సెంట్రల్ PFMS ట్రెజరీ గేట్‌వేతో సరిపోల్చబడ్డాయి.",
    "All required land parcels possessed under Section 16, 100% PFMS DBT compensation disbursed, and all displaced families resettled in model colony.": "సెక్షన్ 16 క్రింద అవసరమైన అన్ని భూముల స్వాధీనం, 100% PFMS DBT పరిహారం పంపిణీ మరియు నిరాశ్రయులైన అన్ని కుటుంబాలు మోడల్ కాలనీలో పునరావాసం పొందాయి.",
    "All residential/commercial structures vacated and R&R alternative site possession delivered.": "అన్ని నివాస/వాణిజ్య నిర్మాణాలు ఖాళీ చేయబడ్డాయి మరియు ప్రత్యామ్నాయ సైట్ స్వాధీనం అందించబడింది.",
    "Requisition submitted under Section 3(e) of the RFCTLARR Act 2013 for construction of elevated viaduct, station pier foundations, and multimodal interchange at Hinjewadi IT Park Phase 1. Complete land schedule and socio-economic census records annexed.": "హింజేవాడి ఐటీ పార్క్ ఫేజ్ 1 లో ఎలివేటెడ్ వయాడక్ట్, స్టేషన్ పిల్లర్ పునాదులు మరియు మల్టీమోడల్ ఇంటర్‌ఛేంజ్ నిర్మాణం కొరకు RFCTLARR చట్టం 2013 సెక్షన్ 3(e) కింద ప్రతిపాదన సమర్పించబడింది.",
    "Social Impact Assessment conducted by Gokhale Institute of Politics and Economics. Public hearings concluded at Hinjewadi Gram Panchayat with 86% stakeholder consent. Minimal displacement: only 3 agricultural out-houses affected.": "గోఖలే ఇన్స్టిట్యూట్ ద్వారా సామాజిక ప్రభావ అంచనా (SIA) నిర్వహించబడింది. హింజేవాడి గ్రామ పంచాయతీలో 86% సమ్మతితో ప్రజా విచారణ ముగిసింది.",
    "Standing timber, fruit trees, and perennial crops valuated and signed by Horticulture Dept.": "చెట్లు, పండ్ల తోటలు మరియు పంటల విలువను ఉద్యానవన శాఖ మదింపు చేసి సంతకం చేసింది.",
    "Survey stones planted and boundary coordinates verified on site by Head Surveyor.": "సర్వే రాళ్ళు నాటబడ్డాయి మరియు సరిహద్దు కోఆర్డినేట్లు హెడ్ సర్వేయర్ ద్వారా క్షేత్రస్థాయిలో ధృవీకరించబడ్డాయి.",
    "Pucca constructed dwelling (Min 50 m²) or ₹1.5 Lakh housing grant in model colony.": "పక్కా ఇల్లు (కనీసం 50 చ.మీ) లేదా మోడల్ కాలనీలో ₹1.5 లక్షల గృహనిర్మాణ గ్రాంటు.",
    "₹3,000 per month for 12 months or job skill training quota enrolled.": "12 నెలల పాటు నెలకు ₹3,000 లేదా నైపుణ్య శిక్షణ కోటాలో ప్రవేశం.",
    "₹50,000 per displaced rural family disbursed via Direct Benefit Transfer.": "నిరాశ్రయులైన ప్రతి గ్రామీణ కుటుంబానికి డైరెక్ట్ బెనిఫిట్ ట్రాన్స్‌ఫర్ (DBT) ద్వారా ₹50,000 పంపిణీ చేయబడింది.",
    "These remarks will be permanently committed to the immutable statutory audit log.": "ఈ వ్యాఖ్యలు చట్టబద్ధమైన ఆడిట్ లాగ్‌లో శాశ్వతంగా భద్రపరచబడతాయి.",
    "Submit digital Form 1 proposals, upload corridor shapefiles, and track statutory clearance workflows.": "డిజిటల్ ఫారం 1 ప్రతిపాదనలను సమర్పించండి, కారిడార్ షేప్‌ఫైల్‌లను అప్‌లోడ్ చేయండి మరియు చట్టపరమైన అనుమతులను ట్రాక్ చేయండి.",
    "Advances a proposal or parcel through the shared database and updates all 5 dashboards in real time": "భాగస్వామ్య డేటాబేస్ ద్వారా ప్రతిపాదనను ముందుకు తీసుకెళుతుంది మరియు అన్ని 5 డాష్‌బోర్డ్‌లను నిజ సమయంలో అప్‌డేట్ చేస్తుంది",
