    "Central Ministry Dashboard: Review nationwide multi-state corridors, oversee statutory compliance audits, and MIS velocity curves.": "ಕೇಂದ್ರ ಸಚಿವಾಲಯದ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್: ದೇಶವ್ಯಾಪಿ ಬಹು-ರಾಜ್ಯ ಕಾರಿಡಾರ್‌ಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಶಾಸನಬದ್ಧ ಲೆಕ್ಕಪರಿಶೋಧನೆಗಳನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಿ.",
    "State Revenue Directorate Dashboard: Monitor district land revenue operations, gazette releases, and inter-agency coordination.": "ರಾಜ್ಯ ಕಂದಾಯ ನಿರ್ದೇಶನಾಲಯದ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್: ಜಿಲ್ಲಾ ಭೂ ಕಂದಾಯ ಕಾರ್ಯಾಚರಣೆಗಳು, ಗೆಜೆಟ್ ಬಿಡುಗಡೆಗಳನ್ನು ಮೇಲ್ವಿಚಾರಣೆ ಮಾಡಿ.",
    "District / CALA Officer Dashboard: Scrutinize land titles, conduct Section 15 inquiry hearings, and declare Section 23 awards.": "ಜಿಲ್ಲಾ / CALA ಅಧಿಕಾರಿ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್: ಭೂ ದಾಖಲೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಸೆಕ್ಷನ್ 15 ವಿಚಾರಣೆ ನಡೆಸಿ ಮತ್ತು ಸೆಕ್ಷನ್ 23 ಪರಿಹಾರವನ್ನು ಘೋಷಿಸಿ.",
    "Project Implementing Agency: Submit alignment proposals, upload GIS shapefiles, and request Joint Measurement Surveys (JMS).": "ಯೋಜನಾ ಅನುಷ್ಠಾನ ಸಂಸ್ಥೆ: ಜೋಡಣೆ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ಸಲ್ಲಿಸಿ, GIS ಫೈಲ್‌ಗಳನ್ನು ಅಪ್‌ಲೋಡ್ ಮಾಡಿ ಮತ್ತು ಜಂಟಿ ಅಳತೆ ಸಮೀಕ್ಷೆಯನ್ನು (JMS) ವಿನಂತಿಸಿ.",
    "Citizen Transparency Portal: Search survey records, check compensation solatium calculations, and file hearing objections.": "ನಾಗರಿಕ ಪಾರದರ್ಶಕತೆ ಪೋರ್ಟಲ್: ಸಮೀಕ್ಷೆ ದಾಖಲೆಗಳನ್ನು ಹುಡುಕಿ, ಪರಿಹಾರ ಲೆಕ್ಕಾಚಾರವನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಆಕ್ಷೇಪಣೆಗಳನ್ನು ಸಲ್ಲಿಸಿ.",
